"384 :     public static int gcd(final int p, final int q) {
385 :         int u = p;
386 :         int v = q;
387 :         if ((u == 0) || (v == 0)) {
388 :             if ((u == Integer.MIN_VALUE) || (v == Integer.MIN_VALUE)) {
389 :                 throw new MathArithmeticException(LocalizedFormats.GCD_OVERFLOW_32_BITS,
390 :                                                   p, q);
391 :             }
392 :             return FastMath.abs(u) + FastMath.abs(v);
393 :         }
394 :         // keep u and v negative, as negative integers range down to
395 :         // -2^31, while positive numbers can only be as large as 2^31-1
396 :         // (i.e. we can't necessarily negate a negative number without
397 :         // overflow)
398 :         /* assert u!=0 && v!=0; */
399 :         if (u > 0) {
400 :             u = -u;
401 :         } // make u negative
402 :         if (v > 0) {
403 :             v = -v;
404 :         } // make v negative
405 :         // B1. [Find power of 2]
406 :         int k = 0;
407 :         while ((u & 1) == 0 && (v & 1) == 0 && k < 31) { // while u and v are
408 :                                                             // both even...
409 :             u /= 2;
410 :             v /= 2;
411 :             k++; // cast out twos.
412 :         }
413 :         if (k == 31) {
414 :             throw new MathArithmeticException(LocalizedFormats.GCD_OVERFLOW_32_BITS,
415 :                                               p, q);
416 :         }
417 :         // B2. Initialize: u and v have been divided by 2^k and at least
418 :         // one is odd.
419 :         int t = ((u & 1) == 1) ? v : -(u / 2)/* B3 */;
420 :         // t negative: u was odd, v may be even (t replaces v)
421 :         // t positive: u was even, v is odd (t replaces u)
422 :         do {
423 :             /* assert u<0 && v<0; */
424 :             // B4/B3: cast out twos from t.
425 :             while ((t & 1) == 0) { // while t is even..
426 :                 t /= 2; // cast out twos
427 :             }
428 :             // B5 [reset max(u,v)]
429 :             if (t > 0) {
430 :                 u = -t;
431 :             } else {
432 :                 v = t;
433 :             }
434 :             // B6/B3. at this point both u and v should be odd.
435 :             t = (v - u) / 2;
436 :             // |u| larger: t positive (replace u)
437 :             // |v| larger: t negative (replace v)
438 :         } while (t != 0);
439 :         return -u * (1 << k); // gcd is u*2^k
440 :     }"

